def skill():
    u = Symbol('u')
    us = solve(u**3 - 3*u, u)
    tot = 0
    for v in us:
        tot += 3 if abs(v) < 2 else (2 if abs(v) == 2 else 1)
    return tot

def standard():
    x = Symbol('x')
    f = x**3 - 3*x
    g = expand(f.subs(x, f))
    return len(set(real_roots(Poly(g, x))))

def unique():
    return [standard()]
